static void devices(void){unsigned char p[]={18,1,0,2,0,0,0,64,0x27,6,1,0,0,1,1,2,3,1};Device d,before;U size=0;for(unsigned speed=1;speed<=4;speed++){p[3]=speed==4?3:2;p[7]=speed==4?9:speed==2?8:64;CK(ud_packet(p,8,speed,&size)==0&&size==(speed==4?512:speed==2?8:64));CK(ud_device(p,18,speed,&d)==0&&d.vendor==0x627&&d.product==1&&d.configurations==1&&d.serial==3);for(unsigned n=0;n<18;n++){memset(&d,0xa5,sizeof d);before=d;CK(ud_device(p,n,speed,&d)==TRUNCATED&&!memcmp(&d,&before,sizeof d));}p[7]=0;CK(ud_packet(p,8,speed,&size)==INVALID);}p[3]=2;p[7]=64;p[4]=9;CK(ud_device(p,18,1,&d)==UNSUPPORTED);}
