static void strings(void){unsigned char in[256],out[512],expected[4],before[512];U length,language;unsigned char langs[]={6,3,9,4,0x11,4};CK(ud_language(langs,6,0x411,&language)==0&&language==0x411);CK(ud_language(langs,6,0xffff,&language)==0&&language==0x409);for(U cp=0;cp<=0x10ffff;cp+=17){if(cp>=0xd800&&cp<=0xdfff)continue;unsigned n=4;in[0]=4;in[1]=3;if(cp<65536){in[2]=cp&255;in[3]=cp>>8;}else{U x=cp-65536,high=0xd800+(x>>10),low=0xdc00+(x&1023);in[0]=6;in[2]=high&255;in[3]=high>>8;in[4]=low&255;in[5]=low>>8;n=6;}unsigned want=scalar_utf8(cp,expected);memset(out,0xa5,sizeof out);CK(ud_string(in,n,out,sizeof out,&length)==0&&length==want&&!memcmp(out,expected,want)&&out[want]==0xa5);memset(out,0xa5,sizeof out);memcpy(before,out,sizeof out);length=77;CK(ud_string(in,n,out,want-1,&length)==CAPACITY&&length==77&&!memcmp(out,before,sizeof out));}for(unsigned unit=0xd800;unit<=0xdfff;unit++){in[0]=4;in[1]=3;in[2]=unit&255;in[3]=unit>>8;memset(out,0xa5,sizeof out);memcpy(before,out,sizeof out);CK(ud_string(in,4,out,sizeof out,&length)==INVALID&&!memcmp(out,before,sizeof out));}unsigned char wrong[]={6,3,0,0xd8,0x41,0};memset(out,0xa5,sizeof out);memcpy(before,out,sizeof out);CK(ud_string(wrong,6,out,sizeof out,&length)==INVALID&&!memcmp(out,before,sizeof out));unsigned char same[]={4,3,65,0};CK(ud_string(same,4,same,4,&length)==INVALID);unsigned char maximum[254];maximum[0]=254;maximum[1]=3;for(unsigned i=2;i<254;i+=2){maximum[i]=0x2d;maximum[i+1]=0x4e;}CK(ud_string(maximum,254,out,sizeof out,&length)==0&&length==378);}
